    if not isinstance(payload, dict):
        return {}
    data = payload.get("data")
    if isinstance(data, dict) and isinstance(data.get("gnb"), dict):
        return data["gnb"]
    if isinstance(payload.get("gnb"), dict):  # 중계 계층이 data 를 벗긴 형태 방어
        return payload["gnb"]
    return {}


